import{_ as a,C as e,o,c as s,aj as r,G as p,j as l,a as n}from"./chunks/framework.BZR1KcQy.js";const h=JSON.parse('{"title":"Документ [[ЛКНВ.11100-01 90 03 Руководства администратора.pdf]], стр 332 пакет alterator-limits","description":"","frontmatter":{},"headers":[],"relativePath":"docs/wi/altsp/25.limits.md","filePath":"docs/wi/altsp/25.limits.md","lastUpdated":1788528112000}'),m={name:"docs/wi/altsp/25.limits.md"};function d(c,i,_,u,g,f){const t=e("ImageZoom");return o(),s("div",null,[i[0]||(i[0]=r('<p>Операционная система должна предоставлять графические средства для ограничения пользователей по запуску программ, а также потребления ресурсов.</p><hr><p>Документ [[ЛКНВ.11100-01 99 03 Руководство по комплексу средств защиты.pdf]], стр 199-207 программа [[control++]] www.altlinux.org/Control%2B%2B - это в консоли</p><h1 id="документ-лкнв-11100-01-90-03-руководства-администратора-pdf-стр-332-пакет-alterator-limits" tabindex="-1">Документ [[ЛКНВ.11100-01 90 03 Руководства администратора.pdf]], стр 332 пакет alterator-limits <a class="header-anchor" href="#документ-лкнв-11100-01-90-03-руководства-администратора-pdf-стр-332-пакет-alterator-limits" aria-label="Permalink to &quot;Документ [[ЛКНВ.11100-01 90 03 Руководства администратора.pdf]], стр 332 пакет alterator-limits&quot;">​</a></h1><p>пакет alterator-limits</p><p>Ограничение на использование ресурсов можно настроить в Центр управления системой - Система - Настройка ограничений</p><p>Поле «Domain» может содержать:</p><ul><li>имя пользователя;</li><li>имя группы. Перед именем группы нужно указать символ «@»;</li><li>символ «*». Данное ограничение будет ограничением по умолчанию;</li><li>символ «%» — используется только с ограничением maxlogins. Группа, указанная после %, ограничивает число параллельных сеансов всех пользователей, которые являются членами группы. Если символ «%» используется отдельно, он идентичен использованию «*» с ограничением maxsyslogins;</li><li>диапазон uid, заданный как &lt;min_uid&gt;:&lt;max_uid&gt;;</li><li>диапазон gid, заданный как @&lt;min_gid&gt;:&lt;max_gid&gt;.</li></ul><p>В поле «Type» задается тип ограничения:</p><ul><li>soft — мягкое;</li><li>hard — жёсткое;</li><li>символ «-» — для одновременной установки как мягкого, так и жесткого ограничения.</li></ul><p>Мягкое ограничение определяет число системных ресурсов, которое пользователь может превысить, жёсткое ограничение превысить невозможно. При попытке превысить жёсткое ограничение, пользователь получит сообщение об ошибке.</p><p>Элементом ограничения (поле «Item») может быть:</p><ul><li>core — размер файла core (Кбайт);</li><li>data — максимальный размер данных (Кбайт);</li><li>fsize — максимальный размер файла (Кбайт);</li><li>memlock — максимальное заблокированное адресное пространство (Кбайт);</li><li>nofile — максимальное число открытых файлов;</li><li>stack — максимальный размер стека (Кбайт);</li><li>cpu — максимальное время процессора (минуты);</li><li>nproc — максимальное количество процессов;</li><li>as — ограничение адресного пространства;</li><li>maxlogins — максимальное число одновременных регистраций в системе;</li><li>maxsyslogins — максимальное количество учётных записей;</li><li>priority — приоритет запуска пользовательских процессов;</li><li>locks — максимальное число файлов блокируемых пользователем;</li><li>sigpending — максимальное количество сигналов, которые можно передать процессу;</li><li>msgqueue — максимальный размер памяти для очереди POSIX сообщений (байт);</li><li>nice — максимальный приоритет, который можно выставить: [-20, 19];</li><li>rtprio — максимальный приоритет времени выполнения.</li></ul><p>Для удаления ограничения следует выбрать ограничение в таблице и нажать кнопку «Удалить» и затем кнопку «Применить».</p>',14)),p(t,{src:"/img/alt-limits.png"}),i[1]||(i[1]=l("h1",{id:"ограничение-на-запуск-приложении-режим-киоска",tabindex:"-1"},[n("Ограничение на запуск приложений - режим Киоска "),l("a",{class:"header-anchor",href:"#ограничение-на-запуск-приложении-режим-киоска","aria-label":'Permalink to "Ограничение на запуск приложений - режим Киоска"'},"​")],-1)),i[2]||(i[2]=l("p",null,"![[19) Режим Киоск]]",-1))])}const T=a(m,[["render",d]]);export{h as __pageData,T as default};
